actions.script:
const L = (text) => ec.l10n.localize(text)
const num = (value) => value == null ? null : (typeof value === 'object' && value.toNumber ? value.toNumber() : Number(value))
bookingDay = /^\d{4}-\d{2}-\d{2}/.test(String(date || '')) ? String(date).substring(0, 10) : ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
// the day's noon in the user's time zone, so the day does not shift
dayText = ec.l10n.format(ec.l10n.parseTimestamp(bookingDay + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'EEEE, MMM d, yyyy')
const [year, month, day] = bookingDay.split('-').map(Number)
const dayAfter = (count) => new Date(Date.UTC(year, month - 1, day + count)).toISOString().substring(0, 10)
previousDay = dayAfter(-1)
nextDay = dayAfter(1)
const out = ec.service.sync().name('ironstone.commons.ScheduleServices.get#Resources').parameter('resourceType', type || 'all').call()
const resources = ec.message.hasError() ? [] : Array.from(out.resourceList || [])
resourceList = resources.map((resource) => ({name: resource.name, resourceType: resource.resourceType, resourceId: resource.resourceId,
    typeLabel: resource.typeLabel || '', site: resource.site || '', capacityText: resource.capacity != null ? String(num(resource.capacity)) : '',
    policyText: resource.requiresApproval ? L('Needs approval') : ''}))
bookingList = []
if (resources.length && !ec.message.hasError()) {
    const names = {}
    for (const resource of resources) names[resource.key] = resource.name
    const booked = ec.service.sync().name('ironstone.commons.ScheduleServices.get#ResourceBookings').parameters({start: bookingDay, end: bookingDay,
        keys: resources.map((resource) => resource.key).join(',')}).call()
    if (!ec.message.hasError()) bookingList = Array.from(booked.bookingList || []).map((booking) => {
        const start = String(booking.start || ''), end = String(booking.end || '')
        return {sortKey: start + '|' + (names[booking.resourceKey] || ''), resourceName: names[booking.resourceKey] || booking.resourceKey,
            timeText: booking.allDay ? L('All day') : start.substring(11, 16) + (end.length > 11 ? ' – ' + end.substring(11, 16) : ''),
            title: booking.title || '', eventId: booking.url ? booking.workEffortId : null, statusLabel: booking.statusLabel || '',
            organizerName: booking.organizerName || ''}
    }).sort((left, right) => left.sortKey < right.sortKey ? -1 : left.sortKey > right.sortKey ? 1 : 0)
}
